import test from 'node:test';import assert from 'node:assert/strict';
import {bossIntent,patternHits,BOSS_PROFILES,drawPattern} from '../boss-patterns.js';import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {floorPlan} from '../frontiers.js';
test('all guardians have three phases, bounded damage and readable windups',()=>{assert.equal(BOSS_PROFILES.length,24);assert.equal(new Set(BOSS_PROFILES.map(p=>p.name)).size,24);for(let chapter=1;chapter<=24;chapter++){const e=makeEnemy('boss',chapter,0,true);e.x=15;e.y=15;const seen=new Set();for(const ratio of [1,.6,.2])for(let turn=1;turn<=3;turn++){e.hp=e.maxHp*ratio;e.turn=turn;const i=bossIntent(e,chapter,{id:0,x:10,y:10});seen.add(i.shape);assert.ok(i.left>=1.8);assert.ok(i.power<=e.power*2.1);assert.ok(i.recovery>=1.4);assert.ok(i.label.includes(' · '));}assert.equal(seen.size,3);}});
test('annulus and cross retain genuine safe zones and render from same dimensions',()=>{const ring={shape:'ring',x:10,y:10,inner:1.65,radius:4.5};assert.equal(patternHits(ring,{x:10,y:10}),false);assert.equal(patternHits(ring,{x:12,y:10}),true);assert.equal(patternHits(ring,{x:15,y:10}),false);const cross={shape:'cross',x:10,y:10};assert.equal(patternHits(cross,{x:12,y:12}),false);assert.equal(patternHits(cross,{x:10,y:12}),true);const calls=[];const c=new Proxy({},{get:(_,key)=>(...args)=>calls.push([key,...args])});assert.ok(drawPattern(c,ring,48));assert.ok(calls.some(a=>a[0]==='arc'&&a[3]===4.5*48));assert.ok(drawPattern(c,cross,48));});
test('boss recovery and pending choreography survive battle saves',()=>{const e=makeEnemy('boss',1,0,true);e.x=8;e.y=8;const hero={id:0,hp:100,maxHp:100,mp:10,maxMp:10,x:2,y:2,status:{}};const b=new Battle({heroes:[hero],enemies:[e]});b.planEnemy(e);const i=e.intent;const saved=b.snapshot();b.restore(saved);assert.deepEqual(b.enemies[0].intent,i);b.executeIntent(b.enemies[0],i);assert.ok(b.enemies[0].status.exposed>=1.4);assert.ok(b.enemies[0].status.stagger>=1.4);});
test('regional maps keep generous open worksite courts',()=>{for(let r=0;r<12;r++)for(let a=0;a<5;a++){const s=floorPlan(r,a);for(let y=16;y<=24;y++)for(let x=21;x<=30;x++)assert.equal(s.floor[y][x],'.');}});
